s32 process_hero_hit_reaction(s32 arg) {
    u8 *m;
    struct HitMessage *tbl;
    struct Moby *mob;
    s32 flag;
    s32 id;
    f32 a, b, e;
    Vec4 v;

    if (g_hero_r.state.control_mode == HERO_MODE_DYING) {
        return 0;
    }
    if (g_hero_r.state.control_mode == HERO_MODE_HURT) {
        return 0;
    }
    if (g_hero_r.state.current == 0x32) {
        return 0;
    }
    if (g_hero_r.invulnerable_frames != 0) {
        return 0;
    }
    if (oltanis_game_mode != 0) {
        return 0;
    }
    g_hero_r.damage_source_moby = 0;
    m = (u8 *)g_hero_r.moby;
    if (m[0xA4] == 0xFF) {
        return 0;
    }
    tbl = &l14_moby_hit_records[m[0xA4]];
    if (tbl->target != m) {
        return 0;
    }
    if ((tbl->flags ^ 1) & 1) {
        return 0;
    }
    level_hero_hit_counts[g_current_level_index]++;
    g_hero_r.damage_source_moby = (struct Moby *)tbl->source;
    hero_hit_count++;
    if (g_hero_r.state.control_mode == HERO_MODE_GRIND) {
        g_hero_r.unk5BE = 1;
        return 0;
    }
    if (arg == 0) {
        return 1;
    }
    release_and_clear_hero_voice_slots();
    flag = 0;
    if (tbl->unk_30 & 1) {
        qcopy(&v, &tbl->unk_10);
        if (*(f32 *)((u8 *)tbl + 0x1C) == 5627.9248046875f) {
            flag = 1;
        }
    } else if (tbl->source != 0) {
        FastVecSub(&v, (u8 *)&g_hero_r + 0x80, tbl->source + 0x10);
    } else {
        v.f[0] = FastCos(FastAddRots(g_hero_r.motion.rot.f[2], 3.1415927f));
        v.f[1] = FastSin(FastAddRots(g_hero_r.motion.rot.f[2], 3.1415927f));
        v.i[2] = 0;
    }
    switch (g_hero_r.vehicle_mode) {
        case 0:
            mob = (struct Moby *)((u8 *)g_hero_r.damage_source_moby);
            if (mob != 0 && (mob->oclass == 0x4EB || mob->oclass == 0x558)) {
                id = 0x80;
            call_ret:
                Hero_TryMoveStateL14(id, 1);
                return 1;
            }
            if (g_hero_r.state.control_mode == 0x16) {
                Hero_TryMoveStateL14(0x6D, 1);
                g_hero_r.motion.resolved_velocity_z.f[2] = g_frame_time * 7.0f;
                return 1;
            }
            Hero_TryMoveStateL14(HERO_STATE_HURT, 1);
            e = g_frame_time;
            a = e * 5.7f;
            b = e * 2.4f;
            if (g_hero_r.on_magnet_ground != 0) {
                a = 0.0f;
                b = e * 1.7f;
            }
            hero_knockback(&v, flag, a, b);
            if (flag != 0 && tbl->unk_28 == 4) {
                v.f[2] += v.f[2];
            }
            break;
        case 3:
            Hero_TryMoveStateL14(HERO_STATE_VEHICLE_MODE_3_HURT, 1);
            hero_knockback(&v, flag, g_frame_time * 5.0f, g_frame_time * 2.4f);
            break;
    }
    FastVecAdd(hero_velocity, hero_velocity, &v);
    FastVecAdd(hero_velocity + 0x20, hero_velocity + 0x20, &v);
    return 1;
}
