void HeroL14_UpdateMoveBlendTargets(void) {
    switch (g_hero_r2.vehicle_mode) {
        case 0:
            g_hero_r2.capsule_top_target = 0.8f;
            g_hero_r2.capsule_bottom_target = 0.7f;
            g_hero_r2.capsule_radius_target = 0.45f;
            break;
        case 3:
            g_hero_r2.capsule_top_target = 0.8f;
            g_hero_r2.capsule_bottom_target = 0.6f;
            g_hero_r2.capsule_radius_target = 0.45f;
            break;
    }
    if (g_hero_r2.state.control_mode == HERO_MODE_JUMP) {
        if (g_hero_r2.state_timer > g_hero_r2.takeoff_frame && g_hero_r2.past_jump_apex == 0)
            g_hero_r2.capsule_bottom_target = g_hero_r2.unk434;
    } else if (g_hero_r2.state.current == HERO_STATE_FALL) {
        g_hero_r2.capsule_bottom_target = 0.5f;
    } else if (g_hero_r2.state.current == HERO_STATE_CROUCH) {
        g_hero_r2.capsule_top_target = 0.35000002f;
    } else if (g_hero_r2.on_ice_ground && g_hero_r2.grounded_frames) {
        g_hero_r2.capsule_top_target = 0.8f;
        g_hero_r2.capsule_bottom_target = 0.9f;
    } else if (g_hero_r2.state.current == HERO_STATE_SINK) {
        g_hero_r2.capsule_radius_target = 0.8f;
    }
    if (!g_hero_r2.wall_hit || g_hero_r2.state.prev_control_mode == HERO_MODE_WATER_SURFACE ||
        g_hero_r2.state.control_mode == HERO_MODE_SWIM || g_hero_r2.base_condition ||
        vec_distance_xy(g_hero_r2.wall_contact_point.f, g_hero_r2.motion.pos.f) > g_hero_r2.capsule_radius * 0.5f) {
        f32 *q = g_hero_capsule_top;
        Hero *b = (Hero *)((u8 *)q - 0x220);
        func_00214D28_235D0(b->capsule_top_target, frame_scale * 0.02f, q);
        func_00214D28_235D0(b->capsule_bottom_target, frame_scale * 0.02f, q + 1);
        func_L00_0025C918_235D0(q + 5, q + 6, b->capsule_radius_target, g_frame_scale_sq * 0.02f,
                                g_frame_scale_sq * 0.3f, g_frame_time * 4.0f);
    }
}
